        return res.status(404).json({ error: 'Conversation not found' });
      }
      res.json(conversation);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      console.error('Update conversation error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Messages routes
  app.get('/api/conversations/:id/messages', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { search, limit, offset } = req.query;
      const messages = await storage.getMessagesByConversation(req.params.id, req.user!.tenantId, {
        search: search as string,
        limit: limit ? parseInt(limit as string) : undefined,
        offset: offset ? parseInt(offset as string) : undefined,
      });
      res.json(messages);
    } catch (error) {
      console.error('Get messages error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.post('/api/conversations/:id/messages', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const validatedData = insertMessageSchema.parse({
        ...req.body,
        conversationId: req.params.id,
        tenantId: req.user!.tenantId,
      });

      const message = await storage.createMessage(validatedData);
      res.status(201).json(message);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      console.error('Create message error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Voice Call API endpoints

  // Admin API endpoints (require authentication)
  app.get('/api/calls', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { status, agentId, roomId, contactId, direction, limit, offset } = req.query;
      const calls = await storage.getCallsByTenant(req.user!.tenantId, {
        status: status as string,
        agentId: agentId as string,
        roomId: roomId as string,
        contactId: contactId as string,
        direction: direction as string,
        limit: limit ? parseInt(limit as string) : undefined,
        offset: offset ? parseInt(offset as string) : undefined,
      });
      res.json(calls);
    } catch (error) {
      console.error('Get calls error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.get('/api/calls/:id', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const call = await storage.getCall(req.params.id, req.user!.tenantId);
      if (!call) {
        return res.status(404).json({ error: 'Call not found' });
      }
      res.json(call);
    } catch (error) {
      console.error('Get call error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.put('/api/calls/:id', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      // Use restricted update schema to prevent modification of immutable fields
      const validatedData = updateCallSchema.parse(req.body);
      const call = await storage.updateCall(req.params.id, validatedData, req.user!.tenantId);
      if (!call) {
        return res.status(404).json({ error: 'Call not found' });
      }
      res.json(call);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      console.error('Update call error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.get('/api/rooms', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { status, agentId, limit, offset } = req.query;
      const rooms = await storage.getRoomsByTenant(req.user!.tenantId, {
        status: status as string,
        agentId: agentId as string,
        limit: limit ? parseInt(limit as string) : undefined,
        offset: offset ? parseInt(offset as string) : undefined,
      });
      res.json(rooms);
    } catch (error) {
      console.error('Get rooms error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.get('/api/rooms/:id', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const room = await storage.getRoom(req.params.id, req.user!.tenantId);
      if (!room) {
        return res.status(404).json({ error: 'Room not found' });
      }
      res.json(room);
    } catch (error) {
      console.error('Get room error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Test endpoint for agent conversations (using OpenAI)
  app.post('/api/agents/:id/test', requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { message } = req.body;
      if (!message) {
        return res.status(400).json({ error: 'Message is required' });
      }

      const agent = await storage.getAgent(req.params.id, req.user!.tenantId);
      if (!agent) {
        return res.status(404).json({ error: 'Agent not found' });
      }

      // This would integrate with OpenAI API for real testing
      // For now, return a mock response
      const response = {
        message: `Hello! I'm ${agent.name}, ready to assist you!`,
        agent: agent.name,
        timestamp: new Date().toISOString(),
      };

      res.json(response);
    } catch (error) {
      console.error('Test agent error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Documents API endpoints

  // Get documents with search and filtering
  app.get('/api/documents', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { search, mimeType, source, limit, offset } = req.query;

      const result = await storage.getDocumentsByTenant(req.user!.tenantId, {
        search: search as string,
        mimeType: mimeType as string,
        source: source as string,
        limit: limit ? parseInt(limit as string) : undefined,
        offset: offset ? parseInt(offset as string) : undefined,
      });

      res.json(result);
    } catch (error) {
      console.error('Error fetching documents:', error);
      res.status(500).json({ error: 'Failed to fetch documents' });
    }
  });

  // Get a specific document
  app.get('/api/documents/:id', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { id } = req.params;

      const document = await storage.getDocument(id, req.user!.tenantId);

      if (!document) {
        return res.status(404).json({ error: 'Document not found' });
      }

      res.json(document);
    } catch (error) {
      console.error('Error fetching document:', error);
      res.status(500).json({ error: 'Failed to fetch document' });
    }
  });

  // Create a new document
  app.post('/api/documents', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const validatedData = insertDocumentSchema.parse(req.body);

      const document = await storage.createDocument({
        ...validatedData,
        tenantId: req.user!.tenantId,
        uploadedBy: req.user!.id,
      });

      res.status(201).json(document);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      console.error('Error creating document:', error);
      res.status(500).json({ error: 'Failed to create document' });
    }
  });

  // Update a document
  app.patch('/api/documents/:id', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { id } = req.params;
      const updateData = insertDocumentSchema.partial().parse(req.body);

      const document = await storage.updateDocument(id, updateData, req.user!.tenantId);

      if (!document) {
        return res.status(404).json({ error: 'Document not found' });
      }

      res.json(document);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      console.error('Error updating document:', error);
      res.status(500).json({ error: 'Failed to update document' });
    }
  });

  // Delete a document
  app.delete('/api/documents/:id', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { id } = req.params;

      const deleted = await storage.deleteDocument(id, req.user!.tenantId);

      if (!deleted) {
        return res.status(404).json({ error: 'Document not found' });
      }

      res.json({ message: 'Document deleted successfully' });
    } catch (error) {
      console.error('Error deleting document:', error);
      res.status(500).json({ error: 'Failed to delete document' });
    }
  });

  // Generate presigned URL for document upload
  app.post('/api/uploads/documents-url', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { fileName, mimeType } = req.body;

      if (!fileName || !mimeType) {
        return res.status(400).json({ error: 'fileName and mimeType are required' });
      }

      // Generate unique storage key
      const fileExtension = fileName.split('.').pop();
      const storageKey = `documents/${req.user!.tenantId}/${crypto.randomUUID()}.${fileExtension}`;
      const fullStorageKey = `${process.env.PRIVATE_OBJECT_DIR}/${storageKey}`;

      // For now, return the storage key directly
      // In a full implementation, this would generate a presigned URL
      res.json({
        uploadUrl: `/api/uploads/direct`, // Placeholder URL for direct upload
        storageKey: fullStorageKey,
        fields: {
          key: fullStorageKey,
          'Content-Type': mimeType
        }
      });
    } catch (error) {
      console.error('Error generating upload URL:', error);
      res.status(500).json({ error: 'Failed to generate upload URL' });
    }
  });

  // Agent-Document association endpoints

  // Get documents associated with an agent
  app.get('/api/agents/:agentId/documents', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { agentId } = req.params;
      const { search, limit, offset } = req.query;

      const result = await storage.getAgentDocuments(agentId, req.user!.tenantId, {
        search: search as string,
        limit: limit ? parseInt(limit as string) : undefined,
        offset: offset ? parseInt(offset as string) : undefined,
      });

      res.json(result);
    } catch (error) {
      console.error('Error fetching agent documents:', error);
      res.status(500).json({ error: 'Failed to fetch agent documents' });
    }
  });

  // Add a document to an agent
  app.post('/api/agents/:agentId/documents', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { agentId } = req.params;
      const { documentId } = req.body;

      if (!documentId) {
        return res.status(400).json({ error: 'documentId is required' });
      }

      // Verify the document exists and belongs to the tenant
      const document = await storage.getDocument(documentId, req.user!.tenantId);
      if (!document) {
        return res.status(404).json({ error: 'Document not found' });
      }

      // Verify the agent exists and belongs to the tenant
      const agent = await storage.getAgent(agentId, req.user!.tenantId);
      if (!agent) {
        return res.status(404).json({ error: 'Agent not found' });
      }

      const association = await storage.addAgentDocument({
        tenantId: req.user!.tenantId,
        agentId,
        documentId,
        addedBy: req.user!.id,
      });

      res.status(201).json(association);
    } catch (error) {
      console.error('Error adding document to agent:', error);
      res.status(500).json({ error: 'Failed to add document to agent' });
    }
  });

  // Remove a document from an agent
  app.delete('/api/agents/:agentId/documents/:documentId', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { agentId, documentId } = req.params;

      const removed = await storage.removeAgentDocument(agentId, documentId, req.user!.tenantId);

      if (!removed) {
        return res.status(404).json({ error: 'Association not found' });
      }

      res.json({ message: 'Document removed from agent successfully' });
    } catch (error) {
      console.error('Error removing document from agent:', error);
      res.status(500).json({ error: 'Failed to remove document from agent' });
    }
  });

  // Billing API endpoints

  // Get user credit balance
  app.get('/api/billing/balance', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const billingService = getBillingService();
      const balance = await billingService.getUserBalance(req.user!.id, req.user!.tenantId);

      // Include some additional helpful information
      res.json({ 
        balance,
        formatted: `$${balance.toFixed(3)}`,
        currency: 'USD',
        lastUpdated: new Date().toISOString()
      });
    } catch (error) {
      console.error('Get balance error:', error);
      res.status(500).json({ 
        error: 'Failed to retrieve credit balance', 
        details: 'Please refresh the page or contact support' 
      });
    }
  });

  // Initialize payment
  app.post('/api/billing/topup', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const validatedData = topupSchema.parse(req.body);
      const { amount } = validatedData;
      const { email } = req.user!;

      // Server-side validation for security
      if (!amount || typeof amount !== 'number' || amount < 1 || amount > 1000) {
        return res.status(400).json({ 
          error: 'Invalid amount', 
          details: 'Amount must be between $1 and $1000' 
        });
      }

      const billingService = getBillingService();
      const payment = await billingService.initializePayment(
        req.user!.id,
        req.user!.tenantId,
        amount,
        email
      );

      console.log(`Payment initialized for user ${req.user!.id}: $${amount}`);
      res.json(payment);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: error.errors 
        });
      }

      // Handle specific billing service errors
      if (error instanceof Error) {
        if (error.message.includes('Invalid payment parameters')) {
          return res.status(400).json({ error: error.message });
        }
        if (error.message.includes('Paystack')) {
          return res.status(503).json({ 
            error: 'Payment service temporarily unavailable', 
            details: 'Please try again in a few moments'
          });
        }
      }

      console.error('Initialize payment error:', error);
      res.status(500).json({ error: 'Failed to initialize payment' });
    }
  });

  // Verify payment (public endpoint - accessed via Paystack callback)
  app.get('/api/billing/verify/:reference', async (req, res) => {
    try {
      const { reference } = req.params;

      // Basic validation
      if (!reference || typeof reference !== 'string' || reference.length < 10) {
        console.error(`Invalid payment reference: ${reference}`);
        return res.redirect('/billing?payment=error&reason=invalid_reference');
      }

      console.log(`Processing payment verification for reference: ${reference}`);
      const billingService = getBillingService();
      const verification = await billingService.verifyPayment(reference);

      if (verification.status === 'success' || (verification.data && verification.data.status === 'success')) {
        console.log(`Payment verification successful: ${reference}`);
        res.redirect('/billing?payment=success');
      } else if (verification.status === 'failed' || (verification.data && verification.data.status === 'failed')) {
        console.log(`Payment verification failed: ${reference}`);
        res.redirect('/billing?payment=failed');
      } else {
        console.log(`Payment verification pending/unknown: ${reference}`);
        res.redirect('/billing?payment=pending');
      }
    } catch (error) {
      console.error('Verify payment error:', error);

      // More specific error handling
      if (error instanceof Error) {
        if (error.message.includes('Payment session not found')) {
          return res.redirect('/billing?payment=error&reason=session_not_found');
        }
        if (error.message.includes('already processed')) {
          return res.redirect('/billing?payment=success');
        }
      }

      res.redirect('/billing?payment=error');
    }
  });

  // Get transaction history
  app.get('/api/billing/transactions', authenticateToken, requireTenantAccess, async (req: AuthRequest, res) => {
    try {
      const { type, limit, offset } = req.query;

      // Validate query parameters
      const parsedLimit = limit ? parseInt(limit as string) : 50;
      const parsedOffset = offset ? parseInt(offset as string) : 0;

      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter', 
          details: 'Limit must be between 1 and 100' 
        });
      }

      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter', 
          details: 'Offset must be 0 or greater' 
        });
      }

      if (type && !['topup', 'deduction', 'bonus'].includes(type as string)) {
        return res.status(400).json({ 
          error: 'Invalid type parameter', 
          details: 'Type must be one of: topup, deduction, bonus' 
        });
      }

      const result = await storage.getTransactionsByUser(req.user!.id, req.user!.tenantId, {
        type: type as string,
        limit: parsedLimit,
        offset: parsedOffset,
      });

      res.json(result);
    } catch (error) {
      console.error('Get transactions error:', error);
      res.status(500).json({ error: 'Failed to retrieve transaction history' });
    }
  });

  // Payment verification status endpoint (semi-protected - requires valid reference)
  app.get('/api/billing/verify/:reference/status', async (req, res) => {
    try {
      const { reference } = req.params;

      // Basic validation
      if (!reference || typeof reference !== 'string' || reference.length < 10) {
        return res.status(400).json({ 
          error: 'Invalid reference parameter', 
          details: 'Reference must be a valid payment reference' 
        });
      }

      const session = await storage.getPaymentSessionByReference(reference);

      if (!session) {
        return res.status(404).json({ 
          error: 'Payment session not found', 
          details: 'No payment session found with the provided reference' 
        });
      }

      // Return limited information for security
      res.json({
        status: session.status,
        reference: session.paystackReference,
        amount: parseFloat(session.amount),
        createdAt: session.createdAt,
        completedAt: session.completedAt
      });
    } catch (error) {
      console.error('Get payment status error:', error);
      res.status(500).json({ 
        error: 'Failed to retrieve payment status', 
        details: 'Please try again or contact support if the issue persists' 
      });
    }
  });

}

server/storage.ts.content:
import { 
  users, 
  tenants,
  agents, 
  workflows,
  knowledgeBase,
  callLogs,
  chatLogs,
  webhookLogs,
  webhooks,
  apiKeys,
  contacts,
  agentPreferences,
  conversations,
  messages,
  rooms,
  roomAgents,
  calls,
  llmProviders,
  llmModels,
  llmConfigurations,
  userCredits,
  transactions,
  paymentSessions,
  documents,
  agentDocuments,
  type User, 
  type InsertUser,
  type Tenant,
  type InsertTenant,
  type Agent,
  type InsertAgent,
  type Workflow,
  type InsertWorkflow,
  type KnowledgeBase,
  type InsertKnowledgeBase,
  type CallLog,
  type ChatLog,
  type WebhookLog,
  type Webhook,
  type InsertWebhook,
  type ApiKey,
  type InsertApiKey,
  type Contact,
  type InsertContact,
  type AgentPreferences,
  type InsertAgentPreferences,
  type Conversation,
  type InsertConversation,
  type Message,
  type InsertMessage,
  type Room,
  type InsertRoom,
  type RoomAgent,
  type InsertRoomAgent,
  type Call,
  type InsertCall,
  type UserCredits,
  type InsertUserCredits,
  type Transaction,
  type InsertTransaction,
  type PaymentSession,
  type InsertPaymentSession,
  type Document,
  type InsertDocument,
  type AgentDocument,
  type InsertAgentDocument
} from "@shared/schema";
import { db } from "./db";
import { eq, desc, and, or, like, count, sql, gte, lt } from "drizzle-orm";

export interface IStorage {
  // Users
  getUser(id: string): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  getUserByEmail(email: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  // Tenants
  getTenant(id: string): Promise<Tenant | undefined>;
  createTenant(tenant: InsertTenant): Promise<Tenant>;

  // Agents
  getAgentsByTenant(tenantId: string): Promise<Agent[]>;
  getAgent(id: string, tenantId: string): Promise<Agent | undefined>;
  getAgentById(id: string): Promise<Agent | undefined>; // Widget API - no tenant filter
  createAgent(agent: InsertAgent): Promise<Agent>;
  updateAgent(id: string, agent: Partial<InsertAgent>, tenantId: string): Promise<Agent | undefined>;
  deleteAgent(id: string, tenantId: string): Promise<boolean>;

  // Agent Preferences
  getAgentPreferences(agentId: string, tenantId: string): Promise<AgentPreferences | undefined>;
  updateAgentPreferences(agentId: string, preferences: Partial<InsertAgentPreferences>, tenantId: string): Promise<AgentPreferences | undefined>;

  // Contacts
  createContact(contact: InsertContact): Promise<Contact>;
  getContactById(id: string, tenantId: string): Promise<Contact | undefined>;
  getContactsByTenant(tenantId: string, filters?: {
    search?: string;
    status?: string;
    source?: string;
    limit?: number;
    offset?: number;
  }): Promise<Contact[]>;
  updateContact(id: string, contact: Partial<InsertContact>, tenantId: string): Promise<Contact | undefined>;
  deleteContact(id: string, tenantId: string): Promise<boolean>;
  getContactStats(tenantId: string): Promise<{
    total: number;
    active: number;
    newThisMonth: number;
    activePercentage: string;
    recentActivity: number;
    avgInteractions: number;
  }>;

  // Workflows
  getWorkflowsByTenant(tenantId: string): Promise<Workflow[]>;
  getWorkflow(id: string, tenantId: string): Promise<Workflow | undefined>;
  createWorkflow(workflow: InsertWorkflow): Promise<Workflow>;
  updateWorkflow(id: string, workflow: Partial<InsertWorkflow>, tenantId: string): Promise<Workflow | undefined>;
  deleteWorkflow(id: string, tenantId: string): Promise<boolean>;

  // Knowledge Base
  getKnowledgeBaseByTenant(tenantId: string): Promise<KnowledgeBase[]>;
  createKnowledgeBase(kb: InsertKnowledgeBase): Promise<KnowledgeBase>;
  updateKnowledgeBase(id: string, kb: Partial<InsertKnowledgeBase>, tenantId: string): Promise<KnowledgeBase | undefined>;
  deleteKnowledgeBase(id: string, tenantId: string): Promise<boolean>;

  // Call Logs
  getCallLogsByTenant(tenantId: string, filters?: {
    status?: string;
    agentId?: string;
    type?: string;
    search?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ logs: CallLog[]; total: number }>;
  getCallLog(id: string, tenantId: string): Promise<CallLog | undefined>;
  createCallLog(log: Partial<CallLog>): Promise<CallLog>;

  // Chat Logs
  getChatLogsByTenant(tenantId: string, filters?: {
    status?: string;
    agentId?: string;
    type?: string;
    search?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ logs: ChatLog[]; total: number }>;
  getChatLog(id: string, tenantId: string): Promise<ChatLog | undefined>;
  createChatLog(log: Partial<ChatLog>): Promise<ChatLog>;

  // Webhook Logs
  getWebhookLogsByTenant(tenantId: string, filters?: {
    status?: string;
    eventType?: string;
    type?: string;
    search?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ logs: WebhookLog[]; total: number }>;
  getWebhookLog(id: string, tenantId: string): Promise<WebhookLog | undefined>;
  createWebhookLog(log: Partial<WebhookLog>): Promise<WebhookLog>;

  // Webhooks
  getWebhooksByTenant(tenantId: string): Promise<Webhook[]>;
  createWebhook(webhook: InsertWebhook): Promise<Webhook>;
  updateWebhook(id: string, webhook: Partial<InsertWebhook>, tenantId: string): Promise<Webhook | undefined>;
  deleteWebhook(id: string, tenantId: string): Promise<boolean>;

  // API Keys
  getApiKeysByTenant(tenantId: string): Promise<ApiKey[]>;
  createApiKey(apiKey: InsertApiKey): Promise<ApiKey>;
  updateApiKey(id: string, apiKey: Partial<InsertApiKey>, tenantId: string): Promise<ApiKey | undefined>;
  deleteApiKey(id: string, tenantId: string): Promise<boolean>;

  // Conversations
  getConversationsByTenant(tenantId: string, filters?: {
    agentId?: string;
    search?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ conversations: Conversation[]; total: number }>;
  getConversation(id: string, tenantId: string): Promise<Conversation | undefined>;
  getConversationById(id: string): Promise<Conversation | undefined>; // Widget API - no tenant filter
  createConversation(conversation: InsertConversation): Promise<Conversation>;
  updateConversation(id: string, conversation: Partial<InsertConversation>, tenantId: string): Promise<Conversation | undefined>;

  // Messages
  getMessagesByConversation(conversationId: string, tenantId: string, filters?: {
    search?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ messages: Message[]; total: number }>;
  createMessage(message: InsertMessage): Promise<Message>;

  // Analytics
  getDashboardMetrics(tenantId: string): Promise<{
    totalAgents: number;
    totalWorkflows: number;
