});

// LLM Configurations
export const llmConfigurations = pgTable("llm_configurations", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  agentId: varchar("agent_id").notNull(),
  llmProviderId: varchar("llm_provider_id").notNull(),
