import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation } from "@tanstack/react-query";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { insertAgentSchema } from "@shared/schema";
import type { Agent } from "@shared/schema";
import type { AgentTemplate } from "@/lib/types";

// Define form schema directly for better type compatibility
const agentFormSchema = z.object({
  name: z.string().min(1, "Agent name is required"),
  type: z.enum(["conversation_flow", "single_prompt", "multi_prompt", "custom_llm"]),
  voice: z.string().default("alloy"),
  phoneNumber: z.string().optional(),
  prompt: z.string().optional(),
  isActive: z.boolean().default(false),
  config: z.record(z.any()).default({}),
});

type AgentFormData = z.infer<typeof agentFormSchema>;

interface AgentFormProps {
  agent?: Agent | null;
  template?: AgentTemplate | null;
  onSaved: () => void;
  onCancel: () => void;
}

const voiceOptions = [
  { value: "alloy", label: "Alloy (Default)" },
  { value: "echo", label: "Echo" },
  { value: "fable", label: "Fable" },
  { value: "onyx", label: "Onyx" },
  { value: "nova", label: "Nova" },
  { value: "shimmer", label: "Shimmer" },
];

const typeOptions = [
  { value: "single_prompt", label: "Single Prompt" },
  { value: "multi_prompt", label: "Multi Prompt" },
  { value: "conversation_flow", label: "Conversation Flow" },
  { value: "custom_llm", label: "Custom LLM" },
];

export function AgentForm({ agent, template, onSaved, onCancel }: AgentFormProps) {
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isEditing = !!agent;
  const isFromTemplate = !!template;

  // Initialize form with agent data, template data, or defaults
  const getDefaultValues = (): AgentFormData => {
    if (agent) {
      return {
        name: agent.name,
        type: agent.type as "conversation_flow" | "single_prompt" | "multi_prompt" | "custom_llm",
        voice: "alloy", // Voice will be loaded from configuration
        phoneNumber: "", // Phone number not part of agent schema
        prompt: agent.description || "",
        isActive: agent.isActive ?? false,
        config: {}, // Configuration handled separately
      };
    }

    if (template && template.id !== 'blank') {
      return {
        name: template.name,
        type: template.type as "conversation_flow" | "single_prompt" | "multi_prompt" | "custom_llm",
        voice: "alloy",
        phoneNumber: "",
        prompt: template.description,
        isActive: false,
        config: template.config || {},
      };
    }

    // Defaults for blank agent
    return {
      name: "",
      type: "single_prompt",
      voice: "alloy",
      phoneNumber: "",
      prompt: "",
      isActive: false,
      config: {},
    };
  };

  const form = useForm<AgentFormData>({
    resolver: zodResolver(agentFormSchema),
    defaultValues: getDefaultValues(),
  });

  const createMutation = useMutation({
    mutationFn: (data: AgentFormData) => apiRequest('POST', '/api/agents', data),
    onSuccess: () => {
      toast({
        title: "Agent created",
        description: "Your agent has been created successfully.",
      });
      onSaved();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to create agent. Please try again.",
        variant: "destructive",
      });
    },
    onSettled: () => {
      setIsSubmitting(false);
    },
  });

  const updateMutation = useMutation({
    mutationFn: (data: AgentFormData) => 
      apiRequest('PUT', `/api/agents/${agent!.id}`, data),
    onSuccess: () => {
      toast({
        title: "Agent updated",
        description: "Your agent has been updated successfully.",
      });
      onSaved();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update agent. Please try again.",
        variant: "destructive",
      });
    },
    onSettled: () => {
      setIsSubmitting(false);
    },
  });

  const onSubmit = async (data: AgentFormData) => {
    setIsSubmitting(true);

    try {
      if (isEditing) {
        updateMutation.mutate(data);
      } else {
        createMutation.mutate(data);
      }
    } catch (error) {
      console.error('Form submission error:', error);
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle>
            {isEditing ? 'Edit Agent' : 'Create New Agent'}
            {isFromTemplate && !isEditing && (
              <span className="ml-2 text-sm font-normal text-muted-foreground">
                from {template.name}
              </span>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Agent Name</FormLabel>
                    <FormControl>
                      <Input
                        {...field}
                        placeholder="Enter agent name"
                        data-testid="input-agent-name"
                      />
                    </FormControl>
                    <FormDescription>
                      Give your agent a descriptive name.
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="type"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Agent Type</FormLabel>
                      <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger data-testid="select-agent-type">
                            <SelectValue placeholder="Select agent type" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {typeOptions.map((option) => (
                            <SelectItem key={option.value} value={option.value}>
                              {option.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormDescription>
                        Choose how your agent handles conversations.
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="voice"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Voice</FormLabel>
                      <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger data-testid="select-agent-voice">
                            <SelectValue placeholder="Select voice" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {voiceOptions.map((option) => (
                            <SelectItem key={option.value} value={option.value}>
                              {option.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormDescription>
                        Choose the voice for your agent.
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <FormField
                control={form.control}
                name="phoneNumber"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Phone Number (Optional)</FormLabel>
                    <FormControl>
                      <Input
                        {...field}
                        placeholder="+1 (555) 123-4567"
                        data-testid="input-phone-number"
                      />
                    </FormControl>
                    <FormDescription>
                      Enter a phone number if this agent handles voice calls.
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="prompt"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>System Prompt</FormLabel>
                    <FormControl>
                      <Textarea
                        {...field}
                        placeholder="Enter the system prompt that defines your agent's personality and behavior..."
                        rows={6}
                        data-testid="textarea-agent-prompt"
                      />
                    </FormControl>
                    <FormDescription>
                      Define your agent's personality, role, and how it should respond.
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="isActive"
                render={({ field }) => (
                  <FormItem className="flex flex-row items-center justify-between rounded-lg border p-4">
                    <div className="space-y-0.5">
                      <FormLabel className="text-base">
                        Activate Agent
                      </FormLabel>
                      <FormDescription>
                        Enable this agent to start handling conversations.
                      </FormDescription>
                    </div>
                    <FormControl>
                      <Switch
                        checked={field.value}
                        onCheckedChange={field.onChange}
                        data-testid="switch-agent-active"
                      />
                    </FormControl>
                  </FormItem>
                )}
              />

              <div className="flex items-center space-x-4 pt-6">
                <Button
                  type="submit"
                  disabled={isSubmitting}
                  data-testid="button-save-agent"
                  className="flex-1"
                >
                  {isSubmitting ? 'Saving...' : (isEditing ? 'Update Agent' : 'Create Agent')}
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  onClick={onCancel}
                  disabled={isSubmitting}
                  data-testid="button-cancel-agent"
                  className="flex-1"
                >
                  Cancel
                </Button>
              </div>
            </form>
          </Form>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/AgentManagement.ts.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { 
  Bot, 
  Phone, 
  MessageSquare, 
  Settings, 
  Trash2, 
  Edit, 
  Play, 
  Pause,
  Plus,
  ArrowLeft
} from "lucide-react";
import { AgentTemplates } from "@/components/AgentTemplates";
import { AgentForm } from "@/components/AgentForm";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { mockAgentTemplates } from "@/lib/mock-data";
import type { Agent } from "@shared/schema";
import type { AgentTemplate } from "@/lib/types";

type ViewMode = 'list' | 'templates' | 'form' | 'details';

export function AgentManagement() {
  const { toast } = useToast();
  const [currentView, setCurrentView] = useState<ViewMode>('list');
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<AgentTemplate | null>(null);

  // Fetch agents
  const { data: agents = [], isLoading } = useQuery<Agent[]>({
    queryKey: ['/api/agents'],
  });

  // Delete agent mutation
  const deleteMutation = useMutation({
    mutationFn: (agentId: string) => apiRequest('DELETE', `/api/agents/${agentId}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/agents'] });
      toast({
        title: "Agent deleted",
        description: "The agent has been successfully removed.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to delete agent. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Toggle agent active status
  const toggleActiveMutation = useMutation({
    mutationFn: ({ agentId, isActive }: { agentId: string; isActive: boolean }) => 
      apiRequest('PUT', `/api/agents/${agentId}`, { isActive }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/agents'] });
      toast({
        title: "Agent updated",
        description: "Agent status has been updated successfully.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update agent status.",
        variant: "destructive",
      });
    },
  });

  const handleTemplateSelect = (template: AgentTemplate) => {
    setSelectedTemplate(template);
    setSelectedAgent(null);
    setCurrentView('form');
  };

  const handleEditAgent = (agent: Agent) => {
    setSelectedAgent(agent);
    setSelectedTemplate(null);
    setCurrentView('form');
  };

  const handleAgentCreated = () => {
    setCurrentView('list');
    setSelectedTemplate(null);
    setSelectedAgent(null);
    queryClient.invalidateQueries({ queryKey: ['/api/agents'] });
  };

  const handleDeleteAgent = (agentId: string, agentName: string) => {
    if (window.confirm(`Are you sure you want to delete "${agentName}"? This action cannot be undone.`)) {
      deleteMutation.mutate(agentId);
    }
  };

  const handleToggleActive = (agent: Agent) => {
    toggleActiveMutation.mutate({ 
      agentId: agent.id, 
      isActive: !agent.isActive 
    });
  };

  const renderHeader = () => {
    const getTitle = () => {
      switch (currentView) {
        case 'templates':
          return 'Choose Template';
        case 'form':
          return selectedAgent ? 'Edit Agent' : 'Create Agent';
        case 'details':
          return 'Agent Details';
        default:
          return 'AI Agents';
      }
    };

    const getDescription = () => {
      switch (currentView) {
        case 'templates':
          return 'Select a template to get started quickly';
        case 'form':
          return selectedAgent ? 'Update your agent configuration' : 'Configure your new AI agent';
        case 'details':
          return 'View and manage your agent';
        default:
          return 'Manage your voice and chat AI agents';
      }
    };

    return (
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          {currentView !== 'list' && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentView('list')}
              data-testid="button-back-to-list"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back
            </Button>
          )}
          <div>
            <h2 className="text-2xl font-bold text-foreground">{getTitle()}</h2>
            <p className="text-muted-foreground">{getDescription()}</p>
          </div>
        </div>

        {currentView === 'list' && (
          <Button
            onClick={() => setCurrentView('templates')}
            data-testid="button-create-agent"
            className="hover-elevate"
          >
            <Plus className="h-4 w-4 mr-2" />
            Create Agent
          </Button>
        )}
      </div>
    );
  };

  const renderAgentList = () => {
    if (isLoading) {
      return (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {[...Array(6)].map((_, i) => (
            <Card key={i}>
              <CardHeader>
                <Skeleton className="h-4 w-20" />
                <Skeleton className="h-6 w-32" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-24" />
              </CardContent>
            </Card>
          ))}
        </div>
      );
    }

    if (agents.length === 0) {
      return (
        <Card className="text-center py-12">
          <CardContent>
            <Bot className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">No agents yet</h3>
            <p className="text-muted-foreground mb-4">
              Create your first AI agent to get started with voice and chat automation.
            </p>
            <Button 
              onClick={() => setCurrentView('templates')}
              data-testid="button-create-first-agent"
            >
              <Plus className="h-4 w-4 mr-2" />
              Create Your First Agent
            </Button>
          </CardContent>
        </Card>
      );
    }

    return (
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {agents.map((agent) => (
          <Card 
            key={agent.id} 
            className="hover-elevate cursor-pointer"
            data-testid={`card-agent-${agent.id}`}
          >
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  {agent.type === 'conversation_flow' ? (
                    <MessageSquare className="h-5 w-5 text-blue-600" />
                  ) : (
                    <Bot className="h-5 w-5 text-purple-600" />
                  )}
                  <Badge 
                    variant={agent.isActive ? "default" : "secondary"}
                    className="text-xs"
                  >
                    {agent.isActive ? "Active" : "Inactive"}
                  </Badge>
                </div>
                <div className="flex items-center space-x-1">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleToggleActive(agent);
                    }}
                    data-testid={`button-toggle-${agent.id}`}
                    className="h-8 w-8 p-0"
                  >
                    {agent.isActive ? (
                      <Pause className="h-4 w-4" />
                    ) : (
                      <Play className="h-4 w-4" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleEditAgent(agent);
                    }}
                    data-testid={`button-edit-${agent.id}`}
                    className="h-8 w-8 p-0"
                  >
                    <Edit className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteAgent(agent.id, agent.name);
                    }}
                    data-testid={`button-delete-${agent.id}`}
                    className="h-8 w-8 p-0 text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
              <CardTitle className="text-lg" data-testid={`title-${agent.id}`}>
                {agent.name}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-muted-foreground mb-3 line-clamp-2">
                {agent.description || 'No description available'}
              </p>
              <div className="flex items-center justify-between text-xs text-muted-foreground">
                <span className="flex items-center">
                  {/* Phone number not available in agent schema */}
                  <span className="flex items-center">
                    <Settings className="h-3 w-3 mr-1" />
                    {agent.type.replace('_', ' ')}
                  </span>
                </span>
                <span>
                  Voice: Configuration based
                </span>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'templates':
        return (
          <AgentTemplates 
            templates={mockAgentTemplates}
            onSelectTemplate={handleTemplateSelect}
          />
        );
      case 'form':
        return (
          <AgentForm 
            agent={selectedAgent}
            template={selectedTemplate}
            onSaved={handleAgentCreated}
            onCancel={() => setCurrentView('list')}
          />
        );
      case 'list':
      default:
        return renderAgentList();
    }
  };

  return (
    <div className="space-y-6">
      {renderHeader()}
      {renderContent()}
    </div>
  );
}

